#include <stdio.h>

int main() {
    // for loop implementation in C
    // Printing the numbers 1 to 5
    printf("Pre-test loop implementation\n");
    for (int i = 1; i <= 5; i++) {
        printf("%d\n", i);
    }

    printf("Loop finished\n");

    return 0;
}

#include <stdio.h>

int main() {
    // while loop implementation
    // Printing the numbers 1 to 5
    printf("Pre-test loop implementation\n");
    int i;
    i = 1;
    while (i <= 5) {
        printf("%d\n", i);
        i = i + 1;
    }

    printf("Loop finished\n");

    return 0;
}
